    ["leet", ["leet"]],
    ["", []],
    ["leetcode", ["leet", "code"]],
    ["applepenapple", ["apple", "pen"]],
    ["catsanddog", ["cats", "dog", "sand", "and", "cat"]],
    ["pineapplepenapple", ["pine", "apple"]],
    ["catsandog", ["cats", "dog", "sand", "and", "cat"]],
  ];

  bool wordBreak(String s, List<String> dict) {
    Set<String> dictSet = dict.toSet();
    if (s.isEmpty) return false;
    List<bool> dp = List.filled(s.length + 1, false);
    dp[0] = true;

    for (int i = 1; i <= s.length; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j]) {
          String sub = s.substring(j, i);
          if (dictSet.contains(sub)) {
            dp[i] = true;
            break;
          }
        }
      }
    }

    return dp[s.length];
  }

  void printWordBreak(String s, List<String> dict, bool result) {
    print("String: '$s', Dictionary: $dict, Can segment: $result");
  }

  print("=== Word Break (Can Segment?) ===\n");
  for (var [s, dict] in testCases) {
    printWordBreak(s, dict, wordBreak(s, dict));
  }

  print("\n=== Minimum Word Breaks ===\n");
  for (var [s, dict] in testCases) {
    printWordBreak(s, dict, (wordBreak(s, dict) && s.length < 10)
        ? "Minimum words needed: ${dict.length}"
        : "Cannot segment");
  }

  print("\n=== Word Break II (All Segmentations) ===\n");
  for (var [s, dict] in testCases) {
    final Map<String, List<int>> memo = {};

    List<List<int>> allSegmentations = [];

    void backtrack(int idx, List<String> current, List<int> wordIdx) {
      if (idx == s.length) {
        allSegmentations.add(List.from(wordIdx));
        return;
      }

      for (int i = wordIdx[0]; i < s.length; i++) {
        if (s.substring(i, idx + 1) in dict) {
          wordIdx[0] = i + 1;
          backtrack(idx + 1, current + s.substring(i, idx + 1), wordIdx);
        }
      }
    }

    List<int> wordIdx = [0];
    backtrack(0, [], wordIdx);

    allSegmentations.sort((a, b) {
      for (int i = 0; i < a.length && i < b.length; i++) {
        if (a[i] != b[i]) return a[i].compareTo(b[i]);
      }
      return a.length.compareTo(b.length);
    });

    print("String: '$s', Dictionary: $dict, All possible segmentations:");
    for (final seg in allSegmentations) {
      print(seg);
    }
  }
}

