  bool wordBreak(String s, Set<String> wordDict) {
    Set<String> wordSet = wordDict.toSet();
    List<bool> dp = List.filled(s.length + 1, false);
    dp[0] = true; 

    for (int i = 1; i <= s.length; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j]) {
          String sub = s.substring(j, i);
          if (wordSet.contains(sub)) {
            dp[i] = true;
            break;
          }
        }
      }
    }
    return dp[s.length];
  }

  List<List<String>> wordBreakII(String s, Set<String> wordDict) {
    Set<String> wordSet = wordDict.toSet();
    int n = s.length;
    List<List<String>> results = [];

    List<String?> memo = List.filled(n + 1, null);

    void backtrack(int idx, List<String> curr, List<String?> prev) {
      if (idx == n) {
        results.add(List.from(prev));
        return;
      }

      for (int i = idx; i < n; i++) {
        if (wordSet.contains(s.substring(idx, i + 1))) {
          prev[i + 1] = List.from(prev)[i] ?? List.filled(1, s.substring(idx, i + 1)).join();
          backtrack(i + 1, curr + [s.substring(idx, i + 1)], prev);
        }
      }
    }

    backtrack(0, [], memo);
    return results;
  }

  List<String> dictionary = ['leet', 'code'];
  String s1 = "leetcode";
  String s2 = "applepenapple";
  String s3 = "pineapple";
  String s4 = "catsandog";

  bool result1 = wordBreak(s1, dictionary);
  bool result2 = wordBreak(s2, dictionary);
  bool result3 = wordBreak(s3, dictionary);
  bool result4 = wordBreak(s4, dictionary);

  print("=== Word Break (Can Segment?) ===");
  print("String: '$s1', Dictionary: $dictionary");
  print("Can segment: ${result1}");
  print("String: '$s2', Dictionary: $dictionary");
  print("Can segment: ${result2}");
  print("String: '$s3', Dictionary: $dictionary");
  print("Can segment: ${result3}");
  print("String: '$s4', Dictionary: $dictionary");
  print("Can segment: ${result4}");

  List<List<String>> segmentations1 = wordBreakII(s1, dictionary);
  List<List<String>> segmentations2 = wordBreakII(s2, dictionary);
  List<List<String>> segmentations3 = wordBreakII(s3, dictionary);

  print("=== Word Break II (All Segmentations) ===");
  print("String: '$s1', Dictionary: ${dictionary.join(' ')}");
  print("All possible segmentations:");
  for (var seg in segmentations1) {
    print(seg);
  }
  print("===");

  print("String: '$s2', Dictionary: ${dictionary.join(' ')}");
  print("All possible segmentations:");
  for (var seg in segmentations2) {
    print(seg);
  }
  print("===");

  print("String: '$s3', Dictionary: ${dictionary.join(' ')}");
  print("All possible segmentations:");
  for (var seg in segmentations3) {
    print(seg);
  }
  print("===");

  int minWordBreak(String s, Set<String> wordDict) {
    Set<String> wordSet = wordDict.toSet();
    int n = s.length;
    List<int> dp = List.filled(n + 1, 0x3F3F3F3F);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] != 0x3F3F3F3F && wordSet.contains(s.substring(j, i))) {
          dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
        }
      }
    }

    return dp[n] == 0x3F3F3F3F ? -1 : dp[n];
  }

  String minBreak = "applepenapple";
  Set<String> minDict = {'apple', 'pen'};

  int minWordCount = minWordBreak(minBreak, minDict);
  if (minWordCount == -1) {
    print("Cannot segment");
  } else {
    print("Minimum words needed: $minWordCount");
  }
}

