bool canSegment(String s, List<String> dictionary) {
  Set<String> dict = dictionary.toSet();
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j]) {
        String sub = s.substring(j, i);
        if (dict.contains(sub)) {
          dp[i] = true;
          break;
        }
      }
    }
  }

  return dp[s.length];
}

void wordBreak(String s, List<String> dictionary, List<List<String>> &wordBreakAll) {
  if (s.isEmpty) {
    wordBreakAll.add([]);
    return;
  }

  for (int i = 0; i < s.length; i++) {
    if (dictionary.contains(s.substring(0, i + 1))) {
      String sub = s.substring(0, i + 1);
      wordBreak(s.substring(i + 1), dictionary, wordBreakAll);
      for (var seg in wordBreakAll) {
        seg.add(sub);
      }
    }
  }
}

int minWordBreaks(String s, List<String> dictionary) {
  Set<String> dict = dictionary.toSet();
  List<int> dp = List.filled(s.length + 1, 0);

  for (int i = 1; i <= s.length; i++) {
    dp[i] = dp[i - 1] + (i >= 2 && s.substring(i - 2, i) == "leet") ? 1 : 0;
  }

  int result = 0;
  int count = 0;

  for (int i = 0; i < s.length; i++) {
    if (dp[i + 1] == 1) {
      count++;
    }
  }

  result = count;

  for (int i = 0; i < s.length; i++) {
    if (dp[i + 1] == 1) {
      result = result < count ? result : count;
      count = 0;
    } else {
      count = 0;
    }
  }

  return result;
}

