    for (int i = 0; i < results.length; i++) {
      print('Query ${i + 1}: ${queries[i]} -> ${results[i]}');
    }
    print('');
  }

  printResults('=== Word Break (Can Segment?) ===',
              [wordBreak(q, dictionary) for q in queries]);

  printResults('=== Minimum Word Breaks ===',
              [
                for (int i = 0; i < queries.length; i++) {
                  if (wordBreak(queries[i], dictionary)) {
                    (dictionary[queries[i]] ?? [])
                        .forEach((word) => dp[i] = true);
                  }
                }
              ]);

