              [
                for (int i = 0; i < queries.length; i++) {
                  if (wordBreak(queries[i], dictionary)) {
                    List<List<String>> segs = [];
                    _wordBreak(queries[i], dictionary, '', segs);
                    print('String: "${queries[i]}", Dictionary: $dictionary');
