void _wordBreak(String s, Set<String> dictionary, String prefix, List<List<String>> results) {
  if (s.isEmpty) {
    results.add(prefix.split(' '));
    return;
  }

  for (int i = 0; i < s.length; i++) {
    String ch = s[i];
    if (dictionary.contains(ch)) {
      String next = prefix + ch;
      _wordBreak(s.substring(i + 1), dictionary, next, results);
    }
  }
}

