bool wordBreak(List<String> wordDict, String s) {

  Set<String> wordSet = wordDict.toSet();
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j]) {
        String sub = s.substring(j, i);
        if (wordSet.contains(sub)) {
          dp[i] = true;
          break;
        }
      }
    }
  }

  return dp[s.length];
}

int minWordBreak(String s, List<String> wordDict) {

  Set<String> wordSet = wordDict.toSet();
  int n = s.length;
  List<int> dp = List.filled(n + 1, 0);
  dp[0] = 0; 

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] != 0 && s.substring(j, i) in wordSet) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }

  return dp[n] == 0 ? -1 : dp[n];
}

List<List<String>> wordBreak2(List<String> wordDict, String s) {

  Set<String> wordSet = wordDict.toSet();
  int n = s.length;
  List<String> dp = List.filled(n + 1, '');
  dp[0] = ''; 

  Map<int, List<String>> subwordToParent = {};

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j].isNotEmpty && s.substring(j, i) in wordSet) {
        subwordToParent[j] = [s.substring(j, i)];
      }
    }
  }

  List<List<String>> result = [];
  void backtrack(int index, String current) {
    if (index == s.length) {
      result.add(List.from(dp[index]));
      return;
    }

    if (subwordToParent.containsKey(index)) {
      for (String sub in subwordToParent[index]!) {
        dp[index + 1] = current + sub;
        backtrack(index + 1, sub);
      }
    }

    for (int j = index; j < s.length; j++) {
      if (dp[j].isNotEmpty) {
        backtrack(j + 1, dp[j]);
      }
    }
  }

  backtrack(0, '');
  return result;
}

void printAllSegmentations(List<List<String>> segmentations) {
  if (segmentations.isEmpty) {
    print('Cannot segment');
    return;
  }

  print('String: "$s", Dictionary: $wordDict');
  print('All possible segmentations:');
  for (int i = 0; i < segmentations.length; i++) {
    String segment = segmentations[i].join(' ');
    print('  $segment');
  }
}

