        if (multiplier > 4.0) {
          multiplier = 4.0;
        }
      } else {
        multiplier = 1.0;
      }
    } else {
      multiplier = 1.0;
      if (hasNext && die == previous) {
        multiplier *= 2.0;
        if (multiplier > 4.0) {
          multiplier = 4.0;
        }
      } else {
        multiplier = 1.0;
      }
    }

    if (die == 2) {
      multiplier = 0.5;
      if (multiplier < 0.0) {
        multiplier = 0.0;
      }
    } else {
      multiplier = multiplier * 0.5;
      if (multiplier < 0.0) {
        multiplier = 0.0;
      }
    }

    score += die * multiplier;
    previous = die;
    hasPrevious = true;
    hasNext = i < rounds.length - 1;
  }

  return score;
}

