  bool recursiveBinSearch(String s, String t, int lo, int hi) {
    if (lo > hi) return false;
    if (t.isEmpty) return lo == hi;
    if (s.isEmpty) return false;

    int first = -1;
    for (int i = lo; i <= hi; i++) {
      if (s[i] == t[0]) {
        first = i;
        break;
      }
    }

    if (first == -1) return false;

    List<bool> dp = List.filled(hi + 1, false);
    dp[first] = true;
    for (int i = first + 1; i <= hi; i++) {
      if (s[i] == t[i - first] && dp[i - first - 1]) {
        dp[i] = true;
      }
    }

    return dp[hi];
  }

  bool iterativeBinSearch(String s, String t) {
    int n = s.length;
    int m = t.length;

    if (n == 0 || m == 0) return false;
    if (m > n) return false;

    List<bool> dp = List.filled(n + 1, false);
    dp[0] = true;

    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < m; j++) {
        if (i > 0 && s[i - 1] == t[j] && dp[i - 1]) {
          dp[i] = true;
          break;
        }
      }
    }

    return dp[n];
  }

  String s = "EXAMPLE";
