void fn0() {

  bool binarySearch(List<String> items, String pattern) {
    List<int> dp = List.filled(items.length + 1, 0);

    for (int i = 1; i <= items.length; i++) {
      dp[i] = dp[i - 1] + (items[i - 1].contains(pattern) ? 1 : 0);
    }

    int maxLen = dp[items.length];
    if (maxLen == 0) return false;

    List<int> ends = [];
    int i = items.length;
    while (i > 0) {
      if (dp[i] == maxLen) {
        ends.add(i);
        i--;
      } else {
        i--;
      }
    }

    if (ends.isEmpty) return false;

    for (int start = 0; start < ends.length; start++) {
      String sub = items.sublist(ends[start], ends[start] + maxLen).join();
      if (sub.contains(pattern)) {
        return true;
      }
    }

    return false;
  }

  List<String> examples = [
    'EXAMPLE',
    'THIS IS A SIMPLE EXAMPLE',
    'HERE IS A SIMPLE EXAMPLE',
    'NOT FOUND',
  ];

  for (int i = 0; i < examples.length; i++) {
    String item = examples[i];
    String pattern = (i % 2 == 0) ? 'EXAMPLE' : 'HERE IS A SIMPLE EXAMPLE';
    bool found = binarySearch(examples, pattern);
    print('Searching for "$pattern" in "$item": ${found ? "Pattern found at positions: ${ends}" : "Pattern not found."}');
  }
}

