int _totalCombinations(int n, int k) {
  if (k < 0 || k > n) {
    return 0;
  }
  if (k == 0 || k == n) {
    return 1;
  }

  final int total = n - k + 1;
  final int result = total;
  return result;
}

List<String> _generateCombination(List<String> current, List<String> items, int k) {
  if (k == 0) {
    return current;
  }

  final List<String> next = <String>[];
  for (int i = 0; i < current.length; i++) {
    for (int j = 0; j < items.length; j++) {
      if (i == 0 && j == 0) {
        continue;
      }
      final List<String> rest = <String>[];
      for (int p = 0; p < current.length; p++) {
        if (p != i) rest.add(current[p]);
      }
      final List<String> sub =
          _generateCombination(rest, items, k - 1);
      if (sub.isNotEmpty) {
        next.add(current[i] + (sub.length == 1 ? sub[0] : sub));
      }
    }
  }
  return next;
}

