int _totalCombinations(int k, int n, List<String> args) {
  int total = 0;
  if (k <= 0 || k > n) {
    return total;
  }

  if (args.length == k) {
    total = 1;
    for (final v in args) {
      total = (total * n) ~/ (n - v);
    }
    return total;
  }

  for (int i = 0; i <= n - k; i++) {
    final List<String> sub = args.toList();
    sub.add(items[i]);
    total += _totalCombinations(k - 1, n - i, sub);
  }

  return total;
}

