            } else {
              if (y1 == val) enclosedThis = true;
            }
          }
          if (enclosedThis) enclosed.add([x1, y1]);
        }
      }

      if (enclosed.isEmpty) {
        results.add(')');
      } else {
        results.add('[');
        current = enclosed;
      }
    } else {
