    int i = indices.length - 1;
    while (i > 0 && indices[i] < indices[i - 1]) {
      i--;
    }
    if (i == 0) {
      return -1;
    }
    int j = indices.length - 1;
    while (j > i) {
      if (indices[j] < indices[i]) {
        break;
      }
      j--;
    }
    final int temp = indices[i];
    indices[i] = indices[j];
    indices[j] = temp;
    return i;
  }

  List<int> queens = [];
  for (int idx = 0; idx < n; idx++) {
    queens.add(idx);
  }

  int solutions = 0;
  const int limit = 1000; 
  const int step = 10; 
  for (int iter = 0; iter < limit; iter++) {

    final int idx = nextPermutation(queens);
    if (idx == -1) {
      solutions++;
      continue;
    }
    final int idxStart = iter % step;
    if (idxStart == 0) {
      print('Solution $iter:');
    }
    final int idxEnd = (idx + 1) % step;
    final int len = idxEnd - idxStart + 1;
    for (int j = idxStart; j < idxEnd; j++) {
      final int qIdx = queens[j];
      final int row = qIdx ~/ 8;
      final int col = qIdx % 8;
