void solveNQueens(int n, {int? current, List<List<int>>? queens}) {

  final List<int> next = List<int>.filled(n, -1);
  final List<List<List<int>>> solutions = [];

  void place(int row) {
    if (row == n) {

      solutions.add(List<int>.from(queens ?? List<int>.filled(n, -1)));
      return;
    }

    for (int col = 0; col < n; col++) {
      bool safe = true;
      for (int i = 0; i < row; i++) {
        final int qCol = queens![i];
        if (qCol == col || 
            (i - row).abs() == (qCol - col).abs()) {
          safe = false;
          break;
        }
      }
      if (safe) {
        next[row] = col;
        place(row + 1);
      }
    }
  }

  if (current == null || next == current) {

    place(0);
  } else {

    next[current[0]] = -1;
  }

  int total = 0;
  for (final List<List<int>> sol in solutions) {
    print('Solution ${sol.length + 1}:');
    for (int i = 0; i < sol.length; i++) {
      final int row = sol[i];
      final int col = sol[i];
      print('Q ${i + 1} at ($row, $col)');
    }
    total++;
  }
  print('Total solutions: $total');
}

