void fn0(List<String> args) {

  int n;
  if (args.isEmpty) {
    n = 8;
  } else {
    final last = args.last;
    final maybe = last.split('>');
    if (maybe.length == 2) {
      final raw = maybe[0].trim();
      final val = int.tryParse(raw);
      if (val != null && val > 0) {
        n = val;
      } else {
        print('N must be a positive integer.');
        print('Usage: dart run script.dart <N>');
        return;
      }
    } else {
      print('Invalid input: $last');
      print('Usage: dart run script.dart <N>');
      return;
    }
  }

  print('Solving N-Queens for N=$n');
  print('--------------------------------');

  const int maxT = 1 << 60;
  int f(List<int> arr, int idx) {
    if (idx == arr.length) {
      return 0;
    }
    int ans = maxT;
    for (int i = 0; i < arr.length; i++) {
      int overlap = arr[i] & arr[idx];
      int count = 0;
      while (overlap != 0) {
        count++;
        overlap &= overlap - 1;
      }
      if (count == 0) {
        continue;
      }
      if ((arr[i] & (1 << (idx + 1))) != 0) {
        continue;
      }
      final cost = (i - idx).abs() + count;
      if (cost < ans) {
        ans = cost;
      }
    }
    return ans;
  }

  List<int> queens = List.generate(n, (i) => i);
  int total = 0;
  void solve(List<int> arr, int idx) {
    if (idx == arr.length) {
      total++;
      print('Solution $total:');
      for (int i = 0; i < arr.length; i++) {
        final row = arr[i].bitLength.toRadixString(2).padLeft(n, '0');
        print('Q ${i + 1}: $row');
      }
      print('');
      return;
    }
    final next = List.from(arr);
    for (int i = 0; i < arr.length; i++) {
      if ((arr[i] & (1 << (idx + 1))) == 0) {
        continue;
      }
      final old = arr[i] & ~next[idx];
      final overlap = old & next[idx];
      int count = 0;
      while (overlap != 0) {
        count++;
        overlap &= overlap - 1;
      }
      if (count == 0) {
        continue;
      }
      final cost = (i - idx).abs() + count;
      if (f(next, idx + 1) < maxT) {
        next[idx] &= old;
        solve(next, idx + 1);
      }
    }
  }

  solve(queens, 0);
  print('Total solutions: $total');
}

