class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.random() : this(
      rand() * 2 - 1, rand() * 2 - 1, rand() * 2 - 1, rand() * 2 - 1);

  const Quaternion.fromList(List<double> list)
      : this(list[0], list[1], list[2], list[3]);

  const Quaternion.identity() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.look(Vector3 axis, double angle) {
    final double s = sin(angle / 2);
    final double c = cos(angle / 2);

    final double x = axis.x * s;
    final double y = axis.y * s;
    final double z = axis.z * s;

    final double w = (axis.x * c + axis.y * z - axis.z * y) / 2;

    return Quaternion(x, y, z, w);
  }

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) => Quaternion(
      x * other.w - y * other.z,
      y * other.w + x * other.z,
      z * other.w - x * other.y,
      w * other.w);

  Quaternion conjugate() => Quaternion(x, y, -z, w);

  double norm2() => x * x + y * y + z * z + w * w;

  Quaternion normalized() {
    final double norm = sqrt(norm2());
    if (norm == 0.0) return Quaternion.zero();
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion inverse() => conjugate() * (1 / norm2());

  Quaternion rotate(Quaternion axis, double angle) {
    final Quaternion axisQ = Quaternion.fromList(axis.toList());
    return Quaternion.look(axisQ, angle) * w;
  }

  @override
  String toString() => 'Quaternion($x, $y, $z, $w)';
}

