  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.identity() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.unitX() : this(1.0, 0.0, 0.0, 0.0);

  const Quaternion.unitY() : this(0.0, 1.0, 0.0, 0.0);

  const Quaternion.unitZ() : this(0.0, 0.0, 1.0, 0.0);

  const Quaternion.unitW() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.fromAxisAngle(
      double ax, double ay, double az, double angle) {
    final sin = math.sin(angle);
    final cos = math.cos(angle);
    return Quaternion(ax * cos - ay * sin, ax * sin + ay * cos, az * cos - az * sin, az * sin + az * cos);
  }

  const Quaternion.fromBasisVectors() {
    return Quaternion.fromAxisAngle(1.0, 0.0, 0.0, 0.0);
  }

  const Quaternion.random() {
    final rand = math.Random(0);
    final x = rand.nextDouble() * 2 - 1;
    final y = rand.nextDouble() * 2 - 1;
    final z = rand.nextDouble() * 2 - 1;
    final w = rand.nextDouble() * 2 - 1;
    return Quaternion(x, y, z, w);
  }

  const Quaternion.fromAxisAngleMatrix(
      List<double> row1, List<double> row2, List<double> row3) {
    final q = Quaternion.fromAxisAngle(row1[0], row1[1], row1[2], row1[3]);
    final r = Quaternion.fromAxisAngle(row2[0], row2[1], row2[2], row2[3]);
    final s = Quaternion.fromAxisAngle(row3[0], row3[1], row3[2], row3[3]);
    return q * r * s;
  }

  const Quaternion conjugate() => Quaternion(x, y, z, -w);

  const Quaternion inverse() {
    final inv = 1 / w;
    return Quaternion(x * inv, y * inv, z * inv, w * inv);
  }

  const Quaternion normalized() {
    final norm = w * w + x * x + y * y + z * z;
    final inv = 1 / norm;
    return Quaternion(x * inv, y * inv, z * inv, w * inv);
  }

  const Quaternion operator +(const other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(const other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

