class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0, 0, 0, 0);

  const Quaternion.unit() : this(1, 0, 0, 1);

  const Quaternion.random() : this(
      rand() * 2 - 1, rand() * 2 - 1, rand() * 2 - 1, rand() * 2 - 1);

  const Quaternion.fromAxisAngle(
      double axisX, double axisY, double axisZ, double angle) {
    final sinA = sin(angle);
    final cosA = cos(angle);
    return Quaternion(
      axisX * cosA + axisZ * sinA,
      axisY * cosA - axisZ * sinA,
      -axisX * sinA + axisZ * cosA,
      cosA,
    );
  }

  const Quaternion.fromBasisVectors(
      const Quaternion& v1, const Quaternion& v2) {
    return Quaternion(
      v1.y * v2.z - v1.z * v2.y,
      v1.z * v2.x - v1.x * v2.z,
      v1.x * v2.y - v1.y * v2.x,
      0,
    );
  }

  const Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  const Quaternion inverse() {
    final invW = 1 / w;
    return Quaternion(x * invW, y * invW, z * invW, w * invW);
  }

  const Quaternion normalized() {
    final norm = sqrt(x * x + y * y + z * z + w * w);
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  const Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(const Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(const Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(const Quaternion other) {
    final q14 = [x, y, z, w];
    final q24 = [other.x, other.y, other.z, other.w];
    final q34 = [
      x * other.x - y * other.y - z * other.z + w * other.w,
      x * other.y + y * other.z - z * other.x + w * other.w,
      x * other.z + y * other.w + z * other.x + w * other.y,
      x * other.w + y * other.z - z * other.y + w * other.x,
    ];
    return Quaternion(q34[0], q34[1], q34[2], q34[3]);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  double norm() {
