bool fn0(List<int> startTimes, List<int> endTimes, List<String> zoneNames, int k) {
  if (startTimes.length != endTimes.length || startTimes.length != zoneNames.length) {
    return false;
  }
  if (k < 0) {
    return false;
  }

  final events = List<Event>.generate(startTimes.length, (i) {
    return Event(i, startTimes[i], endTimes[i], zoneNames[i]);
  });

  events.sort((a, b) {
    if (a.start < b.start) {
      return a.start.compareTo(b.start);
    }
    if (a.start == b.start) {
      return a.end.compareTo(b.end);
    }
    return a.zone.compareTo(b.zone);
  });

  int left = 0;
  int right = events.length;

  while (left < right) {
    final mid = (left + right) ~/ 2;
    if (events[mid].zone.compareTo("Asia/Tokyo") < 0) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  int kIndex = left;
  if (kIndex < events.length &&
      events[kIndex].zone.compareTo("Asia/Tokyo") == 0) {
    kIndex--;
  }

  final needKth = k < events.length && kIndex == k;

  if (needKth) {
    return true;
  }

  final firstOverlap = events[kIndex];
  final earlier = events[kIndex];
  final later = events[kIndex + 1];

  if (firstOverlap.zone.compareTo("Asia/Tokyo") < 0) {
    return false;
  }

  final lower = firstOverlap.start < earlier.start
      ? firstOverlap.start
      : earlier.start;
  final upper = firstOverlap.end > later.end
      ? firstOverlap.end
      : later.end;

  if (upper < lower) {
    return false;
  }

  if (needKth) {
    return true;
  }

  left = kIndex + 1;
  right = events.length;

  while (left < right) {
    final mid = (left + right) ~/ 2;
    if (events[mid].zone.compareTo("Asia/Tokyo") < 0) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  final needKthBefore = k < left && left < events.length &&
      events[left].zone.compareTo("Asia/Tokyo") == 0;

  return needKthBefore;
}

class Event {
  final int index;
  final int start;
  final int end;
  final String zone;

  Event(this.index, this.start, this.end, this.zone);

  @override
  bool operator ==(Object other) =>
      index == other.index &&
      start == other.start &&
      end == other.end &&
      zone == other.zone;

  @override
  int get hashCode => start.hashCode ^ end.hashCode ^ zone.hashCode;

  @override
  String toString() => '$zone: $start - $end';
}

