  int sampleCount = 0;
  bool invert = false;

  for (int i = 0; i < log.length; i++) {
    final ch = log[i];
    if (ch == '!') {
      invert = !invert;
      continue;
    }
    if (ch == 'P') {
      stack.add(0.0);
      continue;
    }
    if (ch == 'B' || ch == 'C' || ch == 'D') {
