      }
      if (red.isNotEmpty && green.isNotEmpty && blue.isNotEmpty) {
        final r = red.removeLast().toDouble();
        final g = green.removeLast().toDouble();
        final b = blue.removeLast().toDouble();
        luminance += (r + g + b) / 3.0;
        sampleCount++;
      }
      continue;
    }
    if (ch != 'S') {
      return 0.0;
    }
    if (stack.length < 2) {
      return 0.0;
    }
    final b = stack.removeLast();
    final a = stack.removeLast();
    final ar = (a * 2.0 - b).clamp(0.0, 1.0);
    stack.add(ar);
  }

