Map<String, int> fn0(List<String> maze, int maxIterations) {
  final int rows = maze.length;
  final int cols = maze[0].length;
  final List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  for (int r = 0; r < rows; r++) {
    if (maze[r].contains('#')) continue;
    dp[r][0] = 1;
  }

  for (int c = 1; c < cols; c++) {
    for (int r = 0; r < rows; r++) {
      final int currentWalls = maze[r][c];

      int best = 0;
      if (r > 0) {
        final int top = dp[r - 1][c];
        if (top > 0 && (currentWalls & 1) == 0) {
          if (dp[r][c - 1] > top + 1) {
            best = top + 1;
          } else {
            best = top;
          }
        }
      }
      if (r > 1) {
        final int bottom = dp[r - 2][c];
        if (bottom > 0 && (currentWalls & 2) == 0) {
          if (dp[r - 1][c - 1] > bottom + 1) {
            best = bottom + 1;
          } else {
            best = bottom;
          }
        }
      }
      if (best > 0) {
        dp[r][c] = best;
      }
    }
  }

  final Map<String, int> result = {};
  for (int r = 0; r < rows; r++) {
    if (dp[r][cols - 1] > 0) {
      final String path = maze.map((row) => row[cols - 1]).join();
      result[path] = dp[r][cols - 1];
    }
  }

