Map<String, int> fn0(List<String> maze, int width) {
  final int n = maze.length;
  final List<List<int>> dp = List.generate(n, (_) => List.filled(width, 0));
  final List<List<int>> sum = List.generate(n, (_) => List.filled(width, 0));
  final List<List<int>> count = List.generate(n, (_) => List.filled(width, 0));
  final List<List<int>> best = List.generate(n, (_) => List.filled(width, -1));

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < width; j++) {
      final int v = maze[i][j] == '#' ? 0 : 1;
      dp[i][j] = v;
    }
  }

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < width; j++) {
      final int v = dp[i][j];
      if (i > 0) {
        dp[i][j] = v > dp[i - 1][j] + 1 ? v : dp[i - 1][j] + 1;
      }
      if (j > 0) {
        final int left = dp[i][j - 1];
        if (dp[i][j] > left + 1) dp[i][j] = left + 1;
      }
    }
  }

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < width; j++) {
      final int v = dp[i][j];
      sum[i][j] = (i > 0) ? sum[i - 1][j] + v : v;
      count[i][j] = (j > 0) ? count[i][j - 1] + 1 : 1;
    }
  }

  for (int i = n - 1; i >= 0; i--) {
    for (int j = width - 1; j >= 0; j--) {
      if (i > 0 && sum[i][j] == sum[i - 1][j]) {
        best[i][j] = best[i - 1][j];
      } else if (j > 0 && count[i][j] > count[i][j - 1]) {
        best[i][j] = best[i][j - 1];
      }
    }
  }

  int maxLen = 0;
  int bestI = -1;
  int bestJ = -1;

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < width; j++) {
      if (best[i][j] >= 0 && best[i][j] > maxLen) {
        maxLen = best[i][j];
        bestI = i;
        bestJ = j;
      }
    }
  }

  return <String, int>{
    'bestI': bestI,
    'bestJ': bestJ,
    'maxLen': maxLen,
  };
}

