Map<String, int> fn0(List<List<String>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return {};
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<int>> memo = List.generate(rows, (_) => List.filled(cols, -1));
  Map<String, int> result = {};
  int maxLen = 0;

  int dfs(int r, int c) {
    if (r < 0 || c < 0 || r >= rows || c >= cols) return 0;
    if (grid[r][c] == '#') return 0;
    if (r == 0 && c == 0) return 1;

    int& val = memo[r][c];
    if (val != -1) return val;

    int up = dfs(r - 1, c);
    int left = dfs(r, c - 1);
    int take = 1 + up + left;

    val = take;
    return take;
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] == '.') {
        int len = dfs(r, c);
        if (len > maxLen) {
          maxLen = len;
          result = {};
        } else if (len == maxLen) {
          result.putIfAbsent(grid[r][c], () => 0);
          result[grid[r][c]] = result[grid[r][c]]! + 1;
        }
      }
    }
  }

  return result;
}

