  final Map<String, int> checksums = {};
  final entries = manifest.replaceAll('\n', ' ').split(' ');
  for (final entry in entries) {
    if (entry.isEmpty) continue;
    final parts = entry.split(':');
    if (parts.length != 2) continue;
    final dest = parts[0].trim();
    final weight = int.tryParse(parts[1].trim());
    if (dest.isEmpty || weight == null) continue;
    final sum = dest.codeUnits.fold(0, (s, c) => s + c);
    checksums[dest] = (checksums[dest] ?? 0) + weight;
  }
  final entriesSorted = checksums.entries.map((e) => '${e.key}:${e.value}').toList();
  entriesSorted.sort();
  return entriesSorted.map((e) => '${e.split(':')[0]}').toList();
}

