    if (pattern.isEmpty) return false;

    List<int> lps = List.filled(pattern.length, 0);
    int length = 0; 
    int i = 1;

    void computeLPSArray(String pattern, int n, List<int> lps) {
      int len = 0; 
      lps[0] = 0; 
      int i = 1;

      while (i < n) {
        if (pattern[i] == pattern[len]) {
          len++;
          lps[i] = len;
          i++;
        } else {
          if (len != 0) len = lps[len - 1];
          else lps[i] = 0;
          i++;
        }
      }
    }

    computeLPSArray(pattern, pattern.length, lps);

    int textLength = text.length;
    int patLength = pattern.length;
    List<int> matchStarts = <int>[]; 
    int patternIndex = 0; 
    int textIndex = 0;

    void search(int patIndex, int textIndex) {
      if (patIndex == patLength) {

        bool isMatch = true;
        for (int j = 0; j < textLength && j < matchStarts.length; j++) {
          if (matchStarts[j] + pattern.length > textIndex) {
            isMatch = false;
            break;
          }
        }
        if (isMatch) {
          for (int idx in matchStarts) {
            print("Found pattern at $idx");
          }
        }
        return;
