        if (patIndex < lps[patIndex]) patIndex = lps[patIndex];
        textIndex = textIndex + patIndex + 1;
        continue;
      }

      matchStarts.add(textIndex);
      textIndex += patIndex;
      patIndex = 0;

      while (patIndex < lps[patIndex]) patIndex++;

      search(patIndex, textIndex);
    }

    search(0, 0);

