String fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 'NaN';
  int rows = grid.length;
  int cols = grid[0].length;
  Map<String, int> memo = {};
  double score = 0.0;
  void dfs(int r, int c) {
    if (r < 0 || c < 0 || r >= rows || c >= cols) {
      return;
    }
    if (grid[r][c] == 0) {
      return;
    }
    if (r == 0 && c == 0) {
      score += 4.0;
      return;
    }
    String key = '$r,$c';
    if (memo.containsKey(key)) {
      double v = memo[key]!;
      if (v == 4.0) return;
      if (v > 0.0 && (r > 0 || c > 0)) {
        score += 0.5;
      }
    }
    int walls = 0;
    List<int> dr = [-1, 1, 0, 0];
    List<int> dc = [0, 0, -1, 1];
    for (int i = 0; i < 4; i++) {
      int nr = r + dr[i];
      int nc = c + dc[i];
      if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) {
        walls++;
      } else if (grid[nr][nc] == 1) {
        walls++;
      }
    }
    double v = 0.0;
    if (walls == 0) {
      v = 4.0;
    } else if (walls == 1) {
      v = 2.0;
    } else {
      v = 0.0;
    }
    score += v;
    memo[key] = v;
    dfs(nr, nc);
  }
  dfs(0, 0);
  double res = score;
  if (res > 4.0) res = 4.0;
  if (res < 0.0) res = 0.0;
  return res.toStringAsFixed(1);
}

