Map<String, int> fn0(List<List<int>> grid) {
  Map<String, int> directions = {
    'N': 0,
    'NE': 1,
    'E': 2,
    'SE': 3,
    'S': 4,
    'SW': 5,
    'W': 6,
    'NW': 7,
  };

  double distance(int r1, int c1, int r2, int c2) {
    int dr = (r2 - r1).abs();
    int dc = (c2 - c1).abs();
    double diagonal = dr > dc ? dr : dc;
    double straight = (dr + dc - 1) * 0.5;
    return diagonal > straight ? diagonal : straight;
  }

  int countNeighbors(int r, int c, int walls) {
    int count = 0;
    int mask = walls & ((1 << (4 * (r + 1))) >> (4 * c + 4));
    for (int i = 0; i < 4; i++) {
      for (int j = 0; j < 4; j++) {
        if ((mask & (1 << i)) != 0) {
          if ((mask & (1 << j)) != 0) {
            count++;
          }
        }
      }
    }
    return count;
  }

  int encode(int walls, int r, int c) {
    int mask = walls & ((1 << (4 * (r + 1))) >> (4 * c + 4));
    int bits = 0;
    for (int i = 0; i < 4; i++) {
      for (int j = 0; j < 4; j++) {
        if ((mask & (1 << i)) != 0) {
          bits |= 1 << j;
        }
      }
    }
    return bits;
  }

  int knightR = 0, knightC = 0, bishopR = 0, bishopC = 0;
  int minDist = 999999;
  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
      int walls = grid[r][c] & 0xF;
      int bits = encode(walls, r, c);
      int dist = (r - knightR).abs() + (c - knightC).abs();
      int bishopDist = (r - bishopR).abs() + (c - bishopC).abs();
      if (dist < minDist) {
        minDist = dist;
        knightR = r;
        knightC = c;
      }
      if (bishopDist < minDist) {
        minDist = bishopDist;
        bishopR = r;
        bishopC = c;
      }
    }
  }

  int knightWalls = walls & 0xF;
  int bishopWalls = walls & 0xF;
  for (int i = 0; i < 4; i++) {
    for (int j = 0; j < 4; j++) {
      if ((knightWalls & (1 << i)) != 0) {
        if ((bishopWalls & (1 << j)) != 0) {
          countNeighbors(knightR + (4 - 1 - i), knightC + (4 - 1 - j), walls) - 1;
        }
      }
    }
  }

  int knightBits = encode(knightWalls, knightR, knightC);
  int bishopBits = encode(bishopWalls, bishopR, bishopC);
  directions[knightR.toStringAsFixed(1) + ',' + knightC.toStringAsFixed(1)] = knightBits;
  directions[bishopR.toStringAsFixed(1) + ',' + bishopC.toStringAsFixed(1)] = bishopBits;
  return directions;
}

