String fn0(List<int> digits, int startDay, int intervalDays) {
  if (digits.isEmpty || intervalDays <= 0) {
    return 'NaN';
  }

  final Map<int, int> counts = {};
  final Map<int, int> ends = {};
  int currentDay = startDay;
  int currentEnd = startDay + intervalDays - 1;
  int activeCount = 0;

  for (int i = 0; i < digits.length; i++) {
    final int day = currentDay + i;
    final int span = digits[i];

    if (day > currentEnd) {
      if (activeCount > 0) {
        ends[currentDay] = currentEnd;
      }
      currentDay = day;
      currentEnd += span;
      activeCount = 1;
    } else if (day == currentEnd + 1) {
      activeCount++;
    }
  }

  if (activeCount > 0) {
    ends[currentDay] = currentEnd;
  }

  for (int d = startDay; d <= currentEnd; d++) {
    counts[d] = (counts[d] ?? 0) + 1;
  }

  final String result = <String>[];
  for (int day = startDay; day <= currentEnd; day++) {
    final int? end = ends[day];
    final int? count = counts[day];

    if (end != null && count != null) {
      final double factor = end - day >= 7 ? 2.0 : (end - day >= 4 ? 1.5 : 1.0);
      final int actual = (count * factor).round();
      result.add('$day:$factor:${actual.toStringAsFixed(1)}');
    }
  }

  return result.isEmpty ? 'NaN' : result.join(',');
}

