  int right = freqs.length - 1;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (freqs[mid] == maxFreq) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  if (freqs[left] != maxFreq) return false;
  int firstIdx = left;
  int thirdIdx = (left + maxFreq) % freqs.length;
  if (firstIdx == thirdIdx) return false;
  int secondIdx = (left + maxFreq ~/ 2) % freqs.length;
  return freqs[firstIdx] == maxFreq && freqs[secondIdx] == maxFreq;
}

