List<int> fn0(List<int> durations, int targetMinutes) {
  int n = durations.length;
  if (n == 0) return [];
  List<int> prefix = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + durations[i] + 1;
  }
  List<int> count = List.filled(n + 1, 0);
  int left = 0;
  for (int right = 1; right <= n; right++) {
