List<int> fn0(List<List<int>> occupancyGrid, int threshold) {
  final int rows = occupancyGrid.length;
  if (rows == 0) return <int>[];
  final int cols = occupancyGrid[0].length;
  final List<int> result = List<int>.filled(cols, 0);
  final List<int> dirs = <int>[1, -1, 0, 0];
  final List<int> dircs = <int>[1, -1, 2, 2];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (occupancyGrid[r][c] >= threshold) {
        int low = 0, high = dirs.length - 1;
        while (low < high) {
          final int mid = (low + high) ~/ 2;
          final int d = dircs[mid];
          final int nr = r + dirs[mid];
          final int nc = c + d;
          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
              occupancyGrid[nr][nc] < threshold) {
            low = mid + 1;
          } else {
            high = mid;
          }
        }
        result[c] = low;
      }
    }
  }
  return result;
}

