@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> weights, int capacity) {
  if (weights.isEmpty) return 0;

  final int n = weights.length;
  final List<int> dp = List<int>.filled(n + 1, 0);

  for (int i = 1; i <= n; i++) {
    final int w = weights[i - 1];
    final int limit = capacity - w;
    final int include = w > 0 ? (i - 1) : 0;
    final int skip = (i - 1 > 0) ? dp[i - 1] : 0;
    dp[i] = limit < 0 ? skip : limit > include ? skip : limit;
  }

  return dp[n];
}

