void convertAndDisplay(bool endian, String suffix) {
  final int value = 0x12345678; 
  final int bytes = value.toRadixString(16).padLeft(8, '0').codeUnitAt(0) == 0x31 ? [0x31, 0x32, 0x33, 0x34] : [0x30, 0x31, 0x32, 0x33];
  final int result = bytes.map(int.codeUnitAt).toRadixString(16).padLeft(8, '0').codeUnitAt(0) == 0x31 ? 0x12345678 : 0;

  String getSuffix(int value) => value.toRadixString(16).padLeft(8, '0').split('').every((c) => c == '0' || c == '1') ? '${suffix.toUpperCase()}' : '${suffix.toLowerCase()}';

  print(getSuffix(endian) + ' Endian Operations:');
  print('--------------------------------');
  print('Original value: 0x${value.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  print('To bytes: [${bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')} = 0x${value.toRadixString(16).toUpperCase().padLeft(8, '0')}]');
  print('From bytes: 0x${bytes.map(int.codeUnitAt).toRadixString(16).padLeft(8, '0')} = 0x${result.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  print('--------------------------------');
}

void bigEndianOperations() => convertAndDisplay(true, 'Big');
