  if (rows < 2 || cols < 2) return [];
  final top = (rowLength > colLength ? rowLength : colLength) ~/ 2;
  final bottom = (rowLength < colLength ? rowLength : colLength) - 1;
  final left = (colLength > rowLength ? colLength : rowLength) ~/ 2;
  final right = (colLength < rowLength ? colLength : rowLength) - 1;
  final topLeft = [top, left];
  final topRight = [top, right];
  final bottomLeft = [bottom, left];
  final bottomRight = [bottom, right];
  final directions = [
    [0, 1],
    [0, -1],
    [1, 0],
    [-1, 0]
  ];
  final regions = <Region>[
    Region(topLeft, topRight, bottomLeft, bottomRight),
    Region(topRight, topLeft, bottomRight, bottomLeft),
    Region(bottomLeft, bottomLeft, bottomRight, topRight),
    Region(bottomRight, bottomRight, topRight, topLeft)
  ];
  final ids = <int>[];
  final rects = <List<int>>[];
  for (final r in regions) {
    final x1 = grid[r.x1][r.y1];
    final y1 = grid[r.x1][r.y1 + 1];
    final x2 = grid[r.x2][r.y2];
    final y2 = grid[r.x2][r.y2 + 1];
    if (x1 >= 0 && x1 <= cols - 1 && y1 >= 0 && y1 <= rows - 1 &&
        x2 >= 0 && x2 <= cols - 1 && y2 >= 0 && y2 <= rows - 1) {
      rects.add([r.x1, r.y1, r.x2, r.y2]);
      ids.add(r.id);
    }
  }
  if (rects.length < 2) return ids;
  final areas = <int>[];
  for (final r in rects) {
    final area = (r[2] - r[0]) * (r[3] - r[1]);
    areas.add(area);
  }
  final indices = List<int>.generate(areas.length, (i) => i);
  final result = List<int>.from(indices);
  final crosses = <int>[];
  while (result.length > 1) {
    final idx1 = result.remove(0);
    final idx2 = result.remove(0);
    final area1 = areas[idx1];
    final area2 = areas[idx2];
    final shared = (area1 & area2) != 0;
    final overlap = shared ? rects[idx1] & rects[idx2] : null;
    if (shared) {
      if (overlap != null) {
        final x1 = overlap.x1 > overlap.x2 ? overlap.x1 : overlap.x2;
        final y1 = overlap.y1 > overlap.y2 ? overlap.y1 : overlap.y2;
        final x2 = overlap.x1 < overlap.x2 ? overlap.x1 : overlap.x2;
        final y2 = overlap.y1 < overlap.y2 ? overlap.y1 : overlap.y2;
        final area = (x2 - x1) * (y2 - y1);
        if (area >= minArea) {
          crosses.add(idx1);
          crosses.add(idx2);
        }
      } else {
        crosses.add(idx1);
        crosses.add(idx2);
      }
    } else {
      result.add(idx1);
      result.add(idx2);
    }
  }
  final unique = <int>[];
  for (final id in crosses) {
    if (!unique.contains(id)) unique.add(id);
  }
  return unique;
}

final class Region {
  final int x1;
  final int y1;
  final int x2;
  final int y2;
  final int id;

  const Region(this.x1, this.y1, this.x2, this.y2, [this.id = 0]);

  @override
  bool operator ==(Object other) =>
      other is Region && x1 == other.x1 && y1 == other.y1 && x2 == other.x2 && y2 == other.y2 && id == other.id;

  @override
  int get hashCode() => x1.hashCode ^ y1.hashCode ^ x2.hashCode ^ y2.hashCode ^ id.hashCode;

  @override
  String toString() => 'Region($id: $x1, $y1 - $x2, $y2)';
}

