  for (int i = 1; i < n; i++) {
    if (dailyDeficitDays[i] >= threshold &&
        dailyDeficitDays[i] - dailyDeficitDays[i - 1] > threshold) {
      int gapStart = dailyDeficitDays[i - 1] + threshold - 1;
      int gapEnd = dailyDeficitDays[i] - 1;
      intervals.add(gapStart);
      intervals.add(gapEnd);
    }
  }

  if (intervals.isNotEmpty) {
    intervals.sort();
    int n1 = intervals.length;
    for (int i = 0; i < n1; i++) {
      if (i + 1 < n1 && intervals[i] + 1 == intervals[i + 1]) {
        continue;
      }
      longestInterval = longestInterval > (intervals[i + 1] - intervals[i])
          ? longestInterval
          : (intervals[i + 1] - intervals[i]);
      distinctIntervals++;
    }
  }

  return {
    'totalDeficitDays': totalDeficit,
    'longestInterval': longestInterval,
    'distinctIntervals': distinctIntervals,
  };
}

