      : this(centerX: cx, centerY: cy, width: 1, height: 1);

  Rectangle.fromPoints(Point p1, Point p2) {
    final double left = p1.x < p2.x ? p1.x : p2.x;
    final double right = p1.x < p2.x ? p2.x : p1.x;
    final double bottom = p1.y < p2.y ? p1.y : p2.y;
    final double top = p1.y < p2.y ? p2.y : p1.y;
    return this(centerX: (left + right) / 2, centerY: (bottom + top) / 2, width: right - left, height: top - bottom);
  }

  bool contains(Point p) =>
      p.x >= centerX - width &&
      p.x <= centerX + width &&
      p.y >= centerY - height &&
      p.y <= centerY + height;

  bool intersects(Rectangle r) =>
      !(r.centerX - r.width > centerX + width ||
        r.centerX + r.width < centerX - width ||
        r.centerY - r.height > centerY + height ||
        r.centerY + r.height < centerY - height);

  bool isUnitSquare() =>
      width == 1 &&
      height == 1 &&
      centerX == 0 &&
