    int idx = random.nextInt(points.length);
    if (!usedIndices.contains(idx)) {
      centroids.add(List.from(points[idx]));
      usedIndices.add(idx);
    }
  }

  List<int> assignments = List.filled(points.length, -1);

  bool converged = false;

  for (int iter = 0; iter < maxIterations && !converged; iter++) {

    converged = true;

    for (int idx = 0; idx < points.length; idx++) {
      double minDist = double.infinity;
      int bestCluster = -1;

