        double dx = points[idx][0] - centroids[cluster][0];
        double dy = points[idx][1] - centroids[cluster][1];
        double dist = math.sqrt(dx * dx + dy * dy);
        if (dist < minDist) {
          minDist = dist;
          bestCluster = cluster;
        }
      }

      if (assignments[idx] != bestCluster) {
        converged = false;
      }

      assignments[idx] = bestCluster;
    }

    List<List<double>> newCentroids =
        List.generate(k, (_) => [double.infinity, double.infinity]);

