      int cluster = assignments[idx];
      double dx = points[idx][0] - centroids[cluster][0];
      double dy = points[idx][1] - centroids[cluster][1];
      newCentroids[cluster][0] = newCentroids[cluster][0] < dx
          ? newCentroids[cluster][0]
          : dx;
      newCentroids[cluster][1] = newCentroids[cluster][1] < dy
          ? newCentroids[cluster][1]
