        indicesInCluster[c.index] = <int>[];
      }
    }

    for (final p in points) {
      final c = indicesInCluster[p.x.abs() + p.y.abs()];

      if (c != null && c.length >= minPts) {
        needsRecluster = true;
        break;
      }
    }

    if (!needsRecluster) {
      final centroids = <Point<double>>[];
      final clusterIds = <int>[];

      for (final p in points) {
        final c = indicesInCluster[p.x.abs() + p.y.abs()];
        if (c != null) {
          centroids.add(p);
          clusterIds.add(c);
        }
      }

      final newClusters = <Cluster<double>>[];
      final newClusterIndex = <int, int>{};

      for (var i = 0; i < centroids.length; i++) {
        final r = newClusters.length;
        final idx = centroids[i].x.abs() + centroids[i].y.abs();
        final bestDist = (r == 0 ? double.infinity : clusters[r - 1].centroid.distance(centroids[i])) * 2;
        if (idx <= bestDist) {
          if (r == 0) {
            newClusters.add(Cluster(centroids[i], i));
          } else {
            final dist = centroids[i].distance(clusters[r - 1].centroid);
            if (dist > bestDist) {
              clusters[r - 1].centroid = centroids[i];
            }
          }
        } else {
          newClusters.add(Cluster(centroids[i], i));
          newClusterIndex[i] = newClusters.length - 1;
        }
      }

      clusters = newClusters;
      clusterIndex = newClusterIndex;
    }
  }

  print('Converged in $iterations iteration(s).');
  for (var i = 0; i < clusters.length; i++) {
    print('Cluster $i: centroid: ${clusters[i].centroid} points: ${clusters[i].points.map((p) => '${p.x.abs().toInt()}/${p.y.abs().toInt()}').toList()}');
  }
}

class Point<double> {
  final double x;
  final double y;

  const Point(this.x, this.y);

  @override
  String toString() => '($x, $y)';

  double distance(Point<double> other) => sqrt(distanceSquared(other));

  double distanceSquared(Point<double> other) => (x - other.x).abs() + (y - other.y).abs();
}

class Cluster<double> {
  final int index;
  final Point<double> centroid;
  final List<Point<double>> points;

  Cluster(this.centroid, this.index);

  void grow(Point<double> point) {
    points.add(point);
    final idx = point.x.abs() + point.y.abs();
    indices.add(idx);
  }

  double distance(Point<double> other) => centroid.distance(other);

  @override
  String toString() => 'Cluster $index: ${points.length} points, centroid: ${centroid}';

  final Set<int> indices = <int>{};
}

