    [7.0, 5.0],
    [7.0, 7.0],
    [1.0, 1.5],
    [1.0, 4.0],
    [1.5, 2.5],
    [2.5, 2.0],
    [2.5, 3.5],
  ];
  int n = points.length;

  int k = 3;
  int maxIterations = 100;
  double tolerance = 0.001;

  List<List<int>> clusters = List.generate(n, (_) => List.filled(2, 0));

  for (int i = 0; i < n; i++) {
    clusters[i][1] = i;
  }

  int clusterId = 0;

  double distance(List<double> a, List<double> b) {
    double sum = 0;
    for (int i = 0; i < a.length; i++) {
      double diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  List<List<double>> centroids = [];

  while (true) {
    List<int> assignments = List.filled(n, 0);

    for (int i = 0; i < k; i++) {
      int idx = rand.nextInt(n);
      centroids.add(List.from(points[idx]));
    }

    for (int step = 0; step < maxIterations; step++) {
      for (int i = 0; i < n; i++) {
        double minDist = double.infinity;
        int bestCluster = 0;

        for (int j = 0; j < k; j++) {
          double dist = distance(points[i], centroids[j]);
          if (dist < minDist) {
            minDist = dist;
            bestCluster = j;
          }
        }

        if (minDist == double.infinity) {
          bestCluster = rand.nextInt(k);
        }

        assignments[i] = bestCluster;
      }

      List<List<double>> sums =
          List.generate(centroids.length, (_) => List.filled(2, 0));

      for (int i = 0; i < n; i++) {
        int c = assignments[i];
        for (int j = 0; j < centroids.length; j++) {
          if (c == j) continue;
          double d = distance(points[i], centroids[j]);
          sums[j][0] += d;
          sums[j][1] += 1;
        }
      }

      for (int i = 0; i < centroids.length; i++) {
        if (sums[i][1] == 0) continue;
        centroids[i][0] = sums[i][0] / sums[i][1];
      }

      double totalChange = 0;
      bool converged = true;

      for (int i = 0; i < n; i++) {
        int oldCluster = assignments[i];
        double oldDist = distance(points[i], centroids[oldCluster[1]]);

        int newCluster = assignments[i];
        double newDist = double.infinity;
        for (int j = 0; j < k; j++) {
          if (j == oldCluster[1]) continue;
          double d = distance(points[i], centroids[j]);
          if (d < newDist) {
            newDist = d;
          }
        }

        totalChange += oldDist - newDist;

        if (totalChange < tolerance) {
          converged = false;
        }
      }

      if (converged) {
        break;
      }
    }

    if (step == maxIterations - 1) {
      print('Cluster analysis has converged in $maxIterations '
          'iteration(s).');
    }
  }

  for (int j = 0; j < k; j++) {
    List<int> pointIndices = [];
    for (int i = 0; i < n; i++) {
      if (assignments[i] == j) {
        pointIndices.add(i);
      }
    }

    print('Cluster $j: ${pointIndices.length} points: ${pointIndices.join(', ')}');
  }

  return clusters;
}

